(() => {
 'use strict';
 const E=TripEngine,BOOT=window.ARGENTINE_CLOUD||null,KEY=BOOT?'argentine-a9-cloud:'+location.pathname:window.ARGENTINE_PREVIEW?'argentine-a9-preview-v1':'argentine-a9-v1';
 let cloud=null,cloudStatus={busy:false,offline:false,count:0,conflicts:[]};
 const $=s=>document.querySelector(s);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 4a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h10a4 4 0 0 1 0 8H7a3 3 0 0 0 0 6h10"/>',book:'<path d="M12 6c-4-3-7-2-9-2v15c3-1 6 0 9 2 3-2 6-3 9-2V4c-3 0-6-1-9 2v15"/>',mountain:'<path d="m2 20 7-15 5 10 3-6 5 11zM6 11l3 2 3-2"/>',hike:'<circle cx="13" cy="4" r="2"/><path d="m9 22 2-9-3-3 3-3 4 5h4M11 13l5 8M19 10v12M8 7l-3 5 3 2"/>',bird:'<path d="M3 19c5 1 12-1 14-7l4-2-4-1a4 4 0 0 0-7-1L5 8l3 5-5 6zM13 10h.01"/>',food:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v19M18 3c-4 5-4 9 0 10V3v19"/>',building:'<path d="m3 8 9-5 9 5H3M4 21h16M6 10v8M12 10v8M18 10v8"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M19 5l-1 1M6 18l-1 1"/>',moon:'<path d="M20 14A9 9 0 0 1 10 4a9 9 0 1 0 10 10Z"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',heart:'<path d="M20.8 5.6a5.2 5.2 0 0 0-7.4 0L12 7l-1.4-1.4a5.2 5.2 0 0 0-7.4 7.4L12 22l8.8-9a5.2 5.2 0 0 0 0-7.4z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5M9 3v16M15 5v16"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',settings:'<path d="M3 6h7m4 0h7M3 12h3m4 0h11M3 18h11m4 0h3"/><circle cx="12" cy="6" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="16" cy="18" r="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',car:'<path d="m5 7 2-4h10l2 4 2 4v8H3v-8l2-4ZM3 11h18M6 15h2M16 15h2M5 19v2M19 19v2M5 7h14"/>',printer:'<path d="M7 8V3h10v5M7 16H3V8h18v8h-4M7 13h10v8H7zM17 11h1"/>',plane:'<path d="m22 2-7 20-3-9L2 9l20-7ZM12 13 22 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',edit:'<path d="m15 3 6 6M4 15 16 3l5 5L9 20l-6 1 1-6z"/>',save:'<path d="M4 3h13l4 4v14H3V3h1ZM7 3v6h10V3M7 21v-8h10v8"/>'};
 const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.pin}</svg>`;
 const photo=id=>PHOTOS[id]?.images?.[0]?.data||PHOTOS[id]?.data||PHOTOS.ba.images?.[0]?.data||PHOTOS.ba.data;
 const effort=['Facile','Modéré','Sportif'];
 const dateFmt=s=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'));
 const num=n=>new Intl.NumberFormat('fr-FR').format(n);
 const active=()=>state.profiles.find(p=>p.id===state.active);
 const counted=()=>state.profiles.filter(E.hasAnswered).length;
 const allPlaces=DATA.destinations.filter(d=>!d.hidden);
 const ui={tab:'explore',query:'',region:'all',theme:'all',scope:'all',map:true,modal:null,gallery:{},mapViews:{},mapBases:{},mapIds:{},visibleRoutes:new Set(DATA.templates.map(t=>t.id)),routeResult:null,selectedPlace:null,hoverPlace:null,selectedRoute:null,hoverRoute:null,mapPanel:null,largeContext:null,lightbox:null};
 let state=E.defaultState(),storageOK=true,initialError='',toastTimer;
 const pack=()=>({format:'argentine-a9',version:1,savedAt:new Date().toISOString(),state});
 try {const saved=localStorage.getItem(KEY);if(saved&&!BOOT)state=E.parseBackup(JSON.parse(saved));else if(BOOT){state=E.clone(BOOT.snapshot.state);const local=saved?JSON.parse(saved):null;if(/^p[1-9]$/.test(local?.active))state.active=local.active;}}catch(error){storageOK=false;initialError='La sauvegarde locale n’a pas pu être chargée. Vous pouvez importer un fichier de sauvegarde.';}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(BOOT?{active:state.active}:pack()));storageOK=true;}catch(error){storageOK=false;}if(cloud)cloud.record(state);renderSaveStatus();}
 function renderSaveStatus(){const el=$('#saveStatus');if(!el)return;if(BOOT){const s=cloudStatus;el.innerHTML=s.conflicts.length?'<button class="text-link" data-action="sync-conflict">Des réponses ont changé · comparer</button>':s.offline?'<button class="text-link" data-action="sync-retry">Connexion interrompue · réessayer</button>':s.busy||s.count?'<span class="dot"></span> Enregistrement…':'<span class="dot"></span> Enregistré pour le groupe';return;}el.innerHTML=storageOK?'<span class="dot"></span> Enregistré sur cet appareil':`<span class="storage-error">${icon('info')} Sauvegarde locale indisponible · exporter</span>`;}
 function receiveCloud(next){const id=state.active,focused=document.activeElement,focusId=focused?.id,selection=focused?.selectionStart;state=next;state.active=id;render();if(focusId){const el=document.getElementById(focusId);if(el){el.focus({preventScroll:true});if(typeof selection==='number'&&el.setSelectionRange)el.setSelectionRange(selection,selection);}}if(ui.modal?.kind==='destination')destinationDialog(ui.modal.id);else if(ui.modal?.kind==='map')renderMapPanel();}
 async function restoreCloud(next,revision){try{await cloud.restore(next,revision);closeDialog();render();toast('La préparation du groupe a été restaurée.');}catch(e){toast(e.message);}}
 function syncConflictDialog(){const items=cloud.conflictDetails(),label=k=>{const [kind,id,item]=k.split(':');const p=state.profiles.find(p=>p.id===id);return kind==='vote'?`${p?.name} · ${E.byId[item]?.name}`:kind==='theme'?`${p?.name} · ${themeLabel(item)}`:kind==='profile'?`Prénom de ${p?.name}`:({settings:'Réglages',selected:'Circuit choisi',notes:'Notes communes'}[k]||k);};const value=v=>v===null?'Sans réponse':typeof v==='object'?JSON.stringify(v):String(v);openDialog(`<div class="dialog-body"><h2 id="dialog-title">Comparer les modifications</h2><p>Ces éléments ont changé pendant votre saisie. Les autres réponses du groupe sont conservées.</p>${items.map(x=>`<section class="alert"><strong>${esc(label(x.key))}</strong><p>Votre saisie : ${esc(value(x.mine))}</p><p>En ligne : ${esc(value(x.theirs))}</p></section>`).join('')}<div class="settings-actions wrap"><button class="btn" data-action="sync-use-online">Garder les réponses en ligne</button><button class="btn primary" data-action="sync-use-mine">Enregistrer ma saisie</button></div></div>`,{kind:'sync-conflict'});}
 function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;toastTimer=setTimeout(()=>$('#toast').textContent='',4500);}
 function navButton(tab,label,ico,count=''){return `<button data-action="nav" data-tab="${tab}" class="${ui.tab===tab?'active':''}" ${ui.tab===tab?'aria-current="page"':''}>${icon(ico)}${label}${count?`<span class="nav-count">${count}</span>`:''}</button>`;}
 function renderSidebar(){
  const colors=['#e8ecdc','#f0e3d1','#dce8e3','#e9dfdb','#dfe8ed','#ece7d3','#e1e8d6','#e4e0eb','#e9ddcf'];
  $('#sidebar').innerHTML=`<div class="brand"><svg class="brand-symbol" viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M4 26h32M8 30h24M12 34h16M10 24a10 10 0 0 1 20 0M20 3v7M6 10l5 5M34 10l-5 5M2 20h6M32 20h6"/></svg><div><div class="brand-name">argentine <i>à 9</i></div><div class="brand-caption">LE VOYAGE COMMENCE ICI</div></div></div><nav class="nav" aria-label="Étapes de préparation">${navButton('explore','Explorer','compass',allPlaces.length)}${navButton('wishes','Nos envies','users',counted()+'/9')}${navButton('routes','Les circuits','route')}${navButton('notebook','Notre carnet','book',state.selected?'1':'')}</nav><div class="sidebar-rule"></div><div class="row between"><span class="eyebrow" style="font-size:9px;color:#8b947f">LES VOYAGEURS</span><span class="small muted" style="font-size:9px">${counted()} / 9 avis</span></div><div class="people-grid" aria-label="Choisir un voyageur">${state.profiles.map((p,i)=>`<button class="person ${p.id===state.active?'active':''}" data-action="person" data-id="${p.id}" aria-label="Saisir les envies de ${esc(p.name)}" aria-pressed="${p.id===state.active}"><span class="avatar" style="--avatar:${colors[i]}">${esc(p.name.startsWith('Voyageur ')?String(i+1):p.name.slice(0,2).toUpperCase())}${E.hasAnswered(p)?'<span class="answered"></span>':''}</span><span class="person-name">${esc(p.name)}</span></button>`).join('')}</div><div class="sidebar-tip"><strong>${icon('users')} On en parle ensemble ?</strong>${BOOT?'Choisis ton prénom et renseigne tes envies. Les réponses se regroupent automatiquement.':'Sélectionne un voyageur, explorez les lieux et note ses envies pendant la visio.'}<button class="text-link" data-action="nav" data-tab="wishes" style="font-size:10px;margin-top:8px">Personnaliser les prénoms</button></div><div class="sidebar-footer"><div class="save-state" id="saveStatus"></div><div class="side-actions"><button class="btn" data-action="export">${icon('download')} Sauvegarder</button><button class="btn" data-action="import">${icon('upload')} Importer</button></div><div class="sidebar-bottom"><button data-action="sources">Sources & crédits</button><button data-action="reset">Recommencer</button></div></div>`;
  renderSaveStatus();
 }
 function renderTop(){
  $('#topbar').innerHTML=`<div><div class="trip-name"><span class="flag" aria-label="Argentine"></span>${window.ARGENTINE_PREVIEW?'Aperçu de test · réponses locales':'Notre grande échappée argentine'}</div><div class="trip-dates">3 — 17 février 2027 <span aria-hidden="true">·</span> Buenos Aires aller-retour</div></div><div class="top-actions"><span class="badge"><span class="dot"></span> ${counted()} voyageurs ont répondu</span><button class="btn ghost" data-action="settings">${icon('settings')} Réglages</button><button class="btn primary" data-action="${state.selected?'nav':'routes'}" ${state.selected?'data-tab="notebook"':''}>${icon(state.selected?'book':'route')}${state.selected?'Notre carnet':'Voir les circuits'}</button></div>`;
 }
 function footer(){return `<footer class="footer-note"><span>${BOOT?'Un lien pour décider ensemble. Vos réponses sont partagées avec le groupe.':'Fait pour décider ensemble. Vos choix restent sur cet appareil.'}</span><div class="row wrap"><button class="text-link" data-action="export" style="font-size:10px">Sauvegarder</button><button class="text-link" data-action="import" style="font-size:10px">Importer</button><button class="text-link" data-action="sources" style="font-size:10px">Sources & méthode</button></div></footer>`;}
 function render(){
  const focused=document.activeElement?.dataset.focus;
  const selection=document.activeElement instanceof HTMLInputElement?document.activeElement.selectionStart:null;
  ui.routeResult=E.suggestions(state);renderSidebar();renderTop();
  $('#main').innerHTML=({explore:renderExplorer,wishes:renderWishes,routes:renderRoutes,notebook:renderNotebook}[ui.tab]||renderExplorer)()+footer();
  if(state.selected)preparePrint();applyMapViews();
  if(focused){const el=[...document.querySelectorAll('[data-focus]')].find(x=>x.dataset.focus===focused);if(el){el.focus({preventScroll:true});if(selection!==null&&el.type==='text')el.setSelectionRange(selection,selection);}}
 }
 function navigate(tab){ui.tab=tab;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
 function stars(id,large=false){const v=active().votes[id];return `<div class="rating ${large?'large':''}" role="group" aria-label="Note de ${esc(active().name)} pour ${esc(E.byId[id].name)}">${[1,2,3,4,5].map(n=>`<button class="${v>=n?'selected':''}" data-action="vote" data-id="${id}" data-score="${n}" data-focus="vote-${id}-${n}${large?'-detail':''}" aria-label="${esc(E.byId[id].name)} : ${n} sur 5 pour ${esc(active().name)}" aria-pressed="${v===n}" title="${['Pas envie','Peu envie','Pourquoi pas','Très envie','Coup de cœur'][n-1]}">${icon('star')}</button>`).join('')}${v?`<button class="clear-vote" data-action="clear-vote" data-id="${id}" aria-label="Retirer le vote pour ${esc(E.byId[id].name)}" title="Retirer ce vote">×</button>`:''}</div>`;}
 function themeLabel(id){return DATA.themes.find(t=>t.id===id)?.label||id;}
 function card(d){const v=E.votesFor(state,d.id);return `<article class="card" data-hover-place="${d.id}"><div class="card-photo"><button data-action="detail" data-id="${d.id}" aria-label="Découvrir ${esc(d.name)}"><img src="${photo(d.id)}" alt="${esc(PHOTOS[d.id]?.title||d.name)}" loading="lazy" decoding="async"></button><span class="location">${esc(d.region)}${d.transit?' · Halte de liaison':d.iconic?' · Emblématique':''}</span><span class="favorite ${(active().votes[d.id]||0)>=4?'loved':''}">${icon('heart')}</span>${!prepared(d.id)?'<span class="distance-label">À explorer · hors circuits préparés</span>':''}</div><div class="card-body"><div class="card-title"><button data-action="detail" data-id="${d.id}">${esc(d.name)}</button></div><p class="card-desc">${esc(d.intro)}</p><div class="card-meta"><span>${icon('clock')}${d.days[0]===d.days[1]?d.days[0]:d.days.join('–')} jour${d.days[1]>1?'s':''}</span><span>${icon('hike')}${effort[d.effort]}</span></div><div class="card-tags">${d.tags.map(t=>`<span>${esc(themeLabel(t))}</span>`).join('')}</div></div><div class="card-vote"><span class="vote-caption">${v.count?`${v.count}/9 avis · ${v.average.toFixed(1).replace('.',',')}/5`:'Ton envie ?'}</span>${stars(d.id)}</div></article>`;}
 function filteredPlaces(){
  const q=ui.query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const order=['iguazu','calafate','chalten','ushuaia','purmamarca','bariloche','ba'];
  return allPlaces.filter(d=>(ui.region==='all'||d.region===ui.region)&&(ui.theme==='all'||d.tags.includes(ui.theme))&&(ui.scope!=='prepared'||prepared(d.id))&&(ui.scope!=='voted'||Object.hasOwn(active().votes,d.id))&&(!q||[d.name,d.region,d.intro,...d.tags.map(themeLabel)].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q))).sort((a,b)=>Number(!!a.transit)-Number(!!b.transit)||Number(!!b.iconic)-Number(!!a.iconic)||(order.indexOf(a.id)<0?99:order.indexOf(a.id))-(order.indexOf(b.id)<0?99:order.indexOf(b.id)));
 }
 function renderExplorer(){const places=filteredPlaces();return `<section class="hero"><div class="hero-copy"><div class="eyebrow">UN PAYS IMMENSE. NEUF FAÇONS DE LE VIVRE.</div><h1>Et si on partait<br><em>à l’aventure ?</em></h1><p>Des envies de chacun au voyage de tous.<br>Explorez, rêvez un peu, puis tracez votre route.</p></div><div class="hero-image"><img src="${PHOTOS.bariloche?.hero||photo('bariloche')}" alt="Bariloche au bord du lac Nahuel Huapi"><span class="hero-counter">${icon('compass')} ${allPlaces.length} destinations à découvrir</span><span class="photo-label">${icon('pin')} Bariloche, Patagonie · au catalogue</span></div></section><section><div class="section-heading"><div><h2>Où vous mèneront vos envies ?</h2><p>Les lieux qui donnent envie de prendre la route.</p></div><div class="view-switch" aria-label="Affichage du catalogue"><button data-action="view" data-map="false" class="${!ui.map?'active':''}" aria-pressed="${!ui.map}">${icon('grid')} Grille</button><button data-action="view" data-map="true" class="${ui.map?'active':''}" aria-pressed="${ui.map}">${icon('map')} Carte</button></div></div><div class="filter-top"><label class="search"><span class="screenreader">Rechercher une destination</span>${icon('search')}<input type="text" id="search" data-focus="search" placeholder="Un lieu, une région, une envie…" value="${esc(ui.query)}"></label><label><span class="screenreader">Filtrer par région</span><select id="regionFilter" data-focus="region">${['all',...new Set(allPlaces.map(d=>d.region))].map(x=>`<option value="${esc(x)}" ${ui.region===x?'selected':''}>${x==='all'?'Toutes les régions':esc(x)}</option>`).join('')}</select></label><label><span class="screenreader">Filtrer les destinations</span><select id="scopeFilter" data-focus="scope"><option value="all" ${ui.scope==='all'?'selected':''}>Tout le catalogue</option><option value="prepared" ${ui.scope==='prepared'?'selected':''}>Circuits préparés</option><option value="voted" ${ui.scope==='voted'?'selected':''}>Mes votes</option></select></label></div><div class="themes-filter" aria-label="Filtrer par envie"><button class="chip ${ui.theme==='all'?'active':''}" data-action="filter-theme" data-theme="all" aria-pressed="${ui.theme==='all'}">Tout explorer</button>${DATA.themes.map(t=>`<button class="chip ${ui.theme===t.id?'active':''}" data-action="filter-theme" data-theme="${t.id}" aria-pressed="${ui.theme===t.id}">${icon(t.icon)}${t.label}</button>`).join('')}</div><div class="explore-info"><span>${places.length} destination${places.length>1?'s':''} · les trajets seront vérifiés dans les circuits</span><span class="active-voter">${icon('edit')} Tu renseignes les envies de <strong>${esc(active().name)}</strong></span></div><div class="${ui.map?'map-layout':''}"><div class="catalog">${places.length?places.map(card).join(''):`<div class="no-results"><h3>Aucun lieu avec ces filtres</h3><p>Élargir la recherche permet de retrouver les destinations du catalogue.</p><button class="btn" data-action="clear-filters">Tout afficher</button></div>`}</div>${ui.map?`<aside class="map-panel"><h3>Le pays en un regard</h3><p>Survolez une fiche pour situer le lieu. Cliquez sur un point pour le découvrir.</p>${mapControls('explore',true,'explore')}${mapSvg(places.map(d=>d.id),null,fullExplorer(),{key:'explore'})}<p>Carte schématique · les points représentent les destinations, pas des distances de route.</p></aside>`:''}</div></section>`;}
 function consensusRows(items){return items.length?items.map(({d,v})=>`<div class="consensus-item"><img src="${photo(d.id)}" alt="" loading="lazy"><div class="consensus-name"><button data-action="detail" data-id="${d.id}">${esc(d.name)}</button><p>${v.count}/9 avis${v.spread>=3?' · avis partagés':''}${!prepared(d.id)?' · hors circuits':''}</p></div><div class="score">${v.average.toFixed(1).replace('.',',')}<small>/5</small></div></div>`).join(''):'<p class="hint" style="padding:25px 0">Les premiers votes feront apparaître vos favoris ici. Les préférences par thème servent déjà à adapter les circuits.</p>';}
 function votedPlaces(){return allPlaces.map(d=>({d,v:E.votesFor(state,d.id)})).filter(x=>x.v.count).sort((a,b)=>b.v.average-a.v.average||b.v.count-a.v.count);}
 function renderWishes(){const p=active(),votes=votedPlaces(),disputed=votes.filter(x=>x.v.spread>=3);return `<div class="page-title"><div class="eyebrow">LES ENVIES DE CHACUN</div><h1>Neuf voyageurs, un beau voyage.</h1><p>Chacun a sa façon de voyager. Notez vos préférences, puis repérez ce qui vous rassemble.</p></div><div class="two-cols"><section class="panel"><div class="profile-head"><div class="profile-icon">${icon('users')}</div><label style="flex:1"><span class="eyebrow" style="font-size:8px;color:#8a957e">ON ÉCOUTE MAINTENANT</span><input type="text" id="profileName" data-focus="profile-name" maxlength="40" value="${esc(p.name)}" aria-label="Prénom du voyageur"></label><button class="icon-btn" data-action="next-person" aria-label="Voyageur suivant">${icon('arrow')}</button></div><p class="small muted" style="margin-bottom:17px">0 = pas envie · 1 = un peu · 2 = bien · 3 = beaucoup<br>Une ligne vide signifie « pas encore demandé ».</p>${DATA.themes.map(t=>`<div class="theme-control"><span class="theme-label">${icon(t.icon)}${t.label}</span><div class="level" role="group" aria-label="${t.label} pour ${esc(p.name)}">${[0,1,2,3].map(v=>`<button data-action="theme" data-theme="${t.id}" data-value="${v}" data-focus="theme-${t.id}-${v}" aria-label="${t.label} : ${v} sur 3" aria-pressed="${p.themes[t.id]===v}" class="${p.themes[t.id]===v?'selected':''}">${v}</button>`).join('')}${Object.hasOwn(p.themes,t.id)?`<button class="reset" data-action="clear-theme" data-theme="${t.id}" aria-label="Effacer ${t.label}">×</button>`:''}</div></div>`).join('')}<div class="profile-metrics">${Object.keys(p.themes).length}/7 thèmes renseignés · ${Object.keys(p.votes).length} destinations notées<br><button class="text-link" data-action="nav" data-tab="explore" style="margin-top:8px">Explorer les lieux pour ${esc(p.name)} ${icon('arrow')}</button></div></section><section class="panel"><div class="row between"><h3>Vos favoris du moment</h3>${icon('heart')}</div><p class="hint">Moyennes des votes exprimés. Les avis manquants ne valent pas zéro.</p>${consensusRows(votes.slice(0,5))}${disputed.length?`<div class="alert" style="margin-top:17px"><strong>On en discute ?</strong><br>${disputed.map(x=>esc(x.d.name)).join(', ')} : au moins 3 points d’écart entre les avis.</div>`:''}</section></div><div class="summary-stats"><div class="stat"><div class="value">${counted()}<span style="font-size:16px;color:#a2ad96"> / 9</span></div><div class="label">voyageurs ont répondu</div></div><div class="stat"><div class="value">${votes.length}</div><div class="label">lieux avec au moins un avis</div></div><div class="stat"><div class="value">${disputed.length}</div><div class="label">destinations à discuter</div></div></div><section class="panel"><div class="row between wrap"><div><h3>Tout le monde autour de la table</h3><p class="hint">Un tiret = aucun vote. Cliquez sur un lieu pour compléter les avis.</p></div><button class="btn primary" data-action="routes">Comparer les circuits ${icon('arrow')}</button></div>${votes.length?`<div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Destination</th>${state.profiles.map(p=>`<th title="${esc(p.name)}">${esc(p.name)}</th>`).join('')}<th>Groupe</th></tr></thead><tbody>${votes.map(({d,v})=>`<tr><td><button data-action="detail" data-id="${d.id}">${esc(d.name)}</button></td>${state.profiles.map(p=>`<td>${p.votes[d.id]?`<span class="table-vote ${p.votes[d.id]>=4?'high':p.votes[d.id]<=2?'low':''}">${p.votes[d.id]}</span>`:'<span class="empty-cell">—</span>'}</td>`).join('')}<td>${v.average.toFixed(1).replace('.',',')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint" style="margin-top:22px">La grille se remplira au fil de vos votes sur les fiches.</p>'}</section>`;}
 const prepared=id=>DATA.templates.some(t=>t.stops.some(s=>[s.id,...s.alternatives].includes(id)));
 function omitted(route){const included=new Set(route.stops.map(s=>s.id));return votedPlaces().filter(({d,v})=>!included.has(d.id)&&v.votes.some(v=>v.score>=4)).map(({d})=>d);}
 function routeExplanation(route,assessment){
  const represented=DATA.themes.map(t=>({label:t.label,weight:route.stops.filter(s=>E.byId[s.id].tags.includes(t.id)&&!E.byId[s.id].transit).reduce((v,s)=>v+s.nights,0)})).sort((a,b)=>b.weight-a.weight).slice(0,3).map(t=>t.label);
  const low=assessment.affinity.responses.filter(p=>p.value<.45),out=omitted(route);
  return `<p><strong>Ce qui vous attend :</strong> ${represented.join(', ').toLowerCase()}.</p><p><strong>Les compromis :</strong> ${esc(DATA.templates.find(t=>t.id===route.templateId).note)}</p>${low.length?`<p><strong>Moins représentés :</strong> ${low.map(p=>esc(p.name)).join(', ')}. Revoir ensemble les étapes.</p>`:''}${out.length?`<p><strong>Envies laissées de côté :</strong> ${out.map(d=>esc(d.name)).join(', ')}. Ces lieux sont dans d’autres boucles ou hors des trajets préparés.</p>`:'<p>Les lieux de différentes régions ne sont pas ajoutés automatiquement à la même boucle.</p>'}<p>Affinité indicative, calculée avec le même poids pour chaque répondant ; ce pourcentage n’est pas un vote unanime.</p>`;
 }
 function routeCard(route,i){const a=route.assessment,t=DATA.templates.find(t=>t.id===route.templateId),top=routeResults().valid.some(r=>r.templateId===t.id);return `<article class="route-card ${a.feasible?'':'route-unavailable'}" data-hover-route="${t.id}"><div class="route-photo"><img src="${photo(t.cover)}" alt="${esc(PHOTOS[t.cover]?.title||t.family)}" loading="lazy"><span class="route-number" style="border-left:4px solid ${routeColor(t.id)}">${top?'TOP 3 · ':''}${a.feasible?'Compatible':'À ajuster'}</span><span class="route-match">${a.affinity.score===null?'À découvrir ensemble':Math.round(a.affinity.score*100)+' % d’affinité'} · ${a.affinity.responses.length}/9 avis</span></div><div class="route-body"><div class="eyebrow">${esc(t.family)}</div><h3><button class="route-title-button" data-action="map-route" data-route-id="${t.id}">${esc(t.title)}</button></h3><p class="route-sub">${esc(t.subtitle)}</p><div class="route-metrics"><div>${a.totalNights}<small>nuits sur place</small></div><div>${num(a.km)}<small>km entre étapes</small></div><div>${E.formatTime(a.drive)}<small>conduite inter-étapes</small></div></div><p class="route-path">${route.stops.map(s=>esc(E.byId[s.id].name)).join(' → ')}</p><p class="small muted">+ ${E.formatTime(a.localDrive)} locale · ${E.formatTime(a.pauses)} de pauses</p>${!a.feasible?`<div class="alert error" style="margin-top:12px"><strong>Pourquoi ce circuit dépasse vos limites</strong><ul>${a.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<details><summary>Pourquoi ce circuit ?</summary>${routeExplanation(route,a)}</details><div class="route-actions"><button class="btn" data-action="map-route" data-route-id="${t.id}">${icon('map')} Carte & étapes</button><button class="btn" data-action="edit-route" data-route-id="${t.id}">Explorer les variantes</button><button class="btn primary" data-action="choose-route" data-route-id="${t.id}" ${a.feasible?'':'disabled'}>${a.feasible?'Choisir & ajuster':'Incompatible actuellement'} ${icon('arrow')}</button></div></div></article>`;}
 function renderRoutes(){const result=routeResults();ui.proposals=result.catalog;return `<div class="page-title"><div class="eyebrow">DES ENVIES À L’ITINÉRAIRE</div><h1>Douze façons de prendre la route.</h1><p>Tous les circuits depuis Buenos Aires, les voyages compatibles en premier. Les trois mieux classés portent le repère « Top 3 ».</p></div><div class="row between wrap" style="margin-bottom:22px"><div class="row wrap"><span class="badge">${result.all.length} circuits compatibles / ${DATA.templates.length}</span><span class="badge">${icon('moon')} ${E.nightsBetween(state.settings.arrival,state.settings.departure)} nuits · ${dateFmt(state.settings.arrival)} — ${dateFmt(state.settings.departure)}</span><span class="badge">${icon('car')} ${state.settings.maxDrive} h maximum / jour</span><span class="badge warm">${state.settings.confirmed?'Dates confirmées':'Dates provisoires'}</span></div><button class="text-link" data-action="settings">Ajuster les contraintes</button></div>${!counted()?'<div class="alert" style="margin-bottom:22px">Personne n’a encore répondu : les circuits compatibles sont classés du moins au plus routier. Renseignez des envies pour personnaliser le classement.</div>':''}${!result.all.length?'<div class="alert error">Aucun circuit compatible avec vos réglages actuels. Les propositions restent consultables ci-dessous.</div>':''}<div class="comparison-layout"><div class="route-grid">${result.catalog.map(routeCard).join('')}</div>${comparisonMap()}</div><section class="panel" style="margin-top:24px"><h3>Du temps pour profiter du voyage.</h3><p class="hint">Les durées au volant comprennent une marge de 15 %. Les pauses sont affichées séparément ; les petits déplacements non planifiés et le trafic restent à prévoir. Une nuit à Buenos Aires précède le départ international. Les tracés sont schématiques et représentent une variante par famille ; les autres étapes sont accessibles dans l’éditeur.</p><button class="text-link" data-action="sources" style="margin-top:14px">Méthode & sources</button></section>`;}
 function routeEditor(id,keep=false){if(!keep)ui.routeDraft=E.clone(findRoute(id));const r=ui.routeDraft,t=DATA.templates.find(t=>t.id===r.templateId);r.assessment=E.evaluate(state,r);openDialog(`<div class="dialog-body"><div class="eyebrow">EXPLORER LES VARIANTES</div><h2 id="dialog-title">${esc(t.title)}</h2><p class="dialog-intro">Testez les étapes et les nuits avant de choisir ce circuit.</p><div data-draft-alerts>${assessmentAlerts(r.assessment)}</div><div class="editor">${r.stops.map((s,i)=>`<div class="stop-editor"><span class="num">${i+1}</span><label><span class="screenreader">Étape ${i+1}</span><select data-draft-stop="${i}">${[t.stops[i].id,...t.stops[i].alternatives].map(id=>`<option value="${id}" ${s.id===id?'selected':''}>${esc(E.byId[id].name)}</option>`).join('')}</select><span class="stop-date">Minimum ${t.stops[i].min} nuit(s)</span></label><label><span class="screenreader">Nuits étape ${i+1}</span><input class="draft-nights" data-draft-nights="${i}" type="number" min="1" max="14" value="${s.nights}"></label></div>`).join('')}</div><div class="settings-actions wrap"><button class="btn" data-action="draft-rebalance">Rééquilibrer les nuits</button><button class="btn primary" data-action="choose-route" data-route-id="${t.id}" data-draft="true" ${r.assessment.feasible?'':'disabled'}>Choisir cette variante</button></div></div>`,{kind:'route-editor'});}
 function dayMarkup(d){const dest=E.byId[d.id];return `<article class="day"><div class="day-date"><strong>${Number(d.date.slice(-2))}</strong><span>février</span></div><div class="day-content"><div class="eyebrow">${esc(dest.name)}${dest.transit?' · HALTE DE LIAISON':''}</div><h3>${esc(d.title)}</h3>${d.transfer?.minutes?`<div class="travel-info">${icon('car')}<span>${esc(E.byId[d.from].name)} → ${esc(dest.name)}<br>${num(d.transfer.km)} km · ${E.formatTime(d.transferDrive)} au volant + ${E.formatTime(E.breaks(d.transferDrive))} de pauses</span></div>`:''}<p>${esc(d.tip)}</p>${d.localDrive?`<p style="margin-top:6px">${icon('car')} Conduite locale prévue : ${E.formatTime(d.localDrive)}, comprise dans l’activité ; pauses en plus.</p>`:''}<div class="sleep-info">${icon('moon')} Nuit à ${esc(d.night)}</div>${dest.overnight?`<p class="small">${esc(dest.overnight)}</p>`:''}<div class="day-links"><button data-action="detail" data-id="${dest.id}">Voir les incontournables</button><a href="https://www.google.com/maps/search/?api=1&query=${dest.lat}%2C${dest.lon}" target="_blank" rel="noopener noreferrer">Ouvrir dans Maps ↗</a>${d.transfer?.minutes?`<a href="https://www.google.com/maps/dir/?api=1&origin=${E.byId[d.from].lat}%2C${E.byId[d.from].lon}&destination=${dest.lat}%2C${dest.lon}&travelmode=driving" target="_blank" rel="noopener noreferrer">Vérifier le trajet ↗</a>`:''}</div></div></article>`;}
 function flightMarkup(date,title,text){return `<article class="day"><div class="day-date"><strong>${Number(date.slice(-2))}</strong><span>février</span></div><div class="day-content"><div class="eyebrow">${icon('plane')} TRANSPORT INTERNATIONAL</div><h3>${title}</h3><p>${text}</p></div></article>`;}
 function itineraryMarkup(a){return `${state.settings.arrival>'2027-02-03'?flightMarkup('2027-02-03','Le départ de l’aventure','Vol aller et trajet jusqu’en Argentine. Horaires à confirmer sur les billets.'):''}${a.days.map(dayMarkup).join('')}${flightMarkup(state.settings.departure,'Départ depuis Buenos Aires','Restitution des véhicules et transfert vers l’aéroport ; horaires à adapter au vol réservé.')}${state.settings.departure<'2027-02-17'?flightMarkup('2027-02-17','Retour à la maison','Fin du voyage international. Vérifier la date d’arrivée effective du vol retour.'):''}`;}
 function assessmentAlerts(a){return `${a.errors.length?`<div class="alert error" role="alert"><strong>Programme à ajuster avant de le retenir</strong><ul>${a.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<div class="alert ok">${icon('check')} ${a.totalNights} nuits réparties · trajets dans la limite · retour à Buenos Aires le ${dateFmt(a.lastArrival)}</div>`}${a.warnings.length?`<div class="alert" style="margin-top:12px">${a.warnings.map(esc).join('<br>')}</div>`:''}`;}
 function renderNotebook(){
  if(!state.selected)return `<div class="page-title"><div class="eyebrow">VOTRE CARNET DE VOYAGE</div><h1>Le début d’une belle histoire.</h1><p>Choisissez un circuit pour commencer à construire votre programme jour par jour.</p></div><div class="no-results">${icon('book')}<h2 style="margin:15px 0">Tout reste à imaginer.</h2><p>Le carnet réunira les étapes, les nuits, les activités et vos notes de visio.</p><button class="btn primary" data-action="routes">Découvrir les circuits ${icon('arrow')}</button></div>`;
  const route=state.selected,t=DATA.templates.find(t=>t.id===route.templateId),a=E.evaluate(state,route);let cursor=state.settings.arrival;
  return `<div class="route-detail-head"><div><div class="eyebrow" style="color:var(--orange)">NOTRE CARNET · ${esc(t.family)}</div><h1>${esc(t.title)}</h1><p>${dateFmt(state.settings.arrival)} — ${dateFmt(state.settings.departure)} 2027 · 9 voyageurs · voiture uniquement</p></div><div class="row wrap"><button class="btn" data-action="routes">Comparer</button><button class="btn primary" data-action="print">${icon('printer')} Imprimer / PDF</button></div></div><div class="plan-layout"><div class="stack">${assessmentAlerts(a)}<section class="panel"><div class="row between wrap"><h3>Les étapes, à votre rythme</h3><button class="text-link" data-action="rebalance">Rééquilibrer les nuits</button></div><p class="hint">Changez une étape ou le nombre de nuits. Le programme s’actualise immédiatement.</p><div class="editor">${route.stops.map((s,i)=>{const date=cursor;cursor=E.plusDays(cursor,s.nights);const slot=t.stops[i];return `<div class="stop-editor"><span class="num">${i+1}</span><div>${slot.alternatives.length?`<label><span class="screenreader">Étape ${i+1}</span><select data-stop-index="${i}" data-focus="stop-${i}">${[slot.id,...slot.alternatives].map(id=>`<option value="${id}" ${id===s.id?'selected':''}>${esc(E.byId[id].name)}</option>`).join('')}</select></label>`:`<div class="stop-name">${esc(E.byId[s.id].name)}${E.byId[s.id].transit?' <span class="badge" style="font-size:8px;padding:2px 5px">Liaison</span>':''}</div>`}<div class="stop-date">${dateFmt(date)} → ${dateFmt(cursor)} · min. ${slot.min} nuit${slot.min>1?'s':''}</div></div><div class="stepper"><button data-action="nights" data-index="${i}" data-delta="-1" data-focus="minus-${i}" aria-label="Retirer une nuit à l’étape ${i+1}" ${s.nights<=1?'disabled':''}>−</button><span>${s.nights} n.</span><button data-action="nights" data-index="${i}" data-delta="1" data-focus="plus-${i}" aria-label="Ajouter une nuit à l’étape ${i+1}" ${s.nights>=14?'disabled':''}>+</button></div></div>`;}).join('')}</div></section><section class="panel"><h3 style="margin-bottom:26px">Au fil des jours</h3>${itineraryMarkup(a)}</section><section class="panel notes"><h3>Les notes de notre visio</h3><p class="hint" style="margin-bottom:14px">Hébergements repérés, décisions, questions et petites idées à garder.</p><label><span class="screenreader">Notes du groupe</span><textarea maxlength="10000" id="tripNotes" maxlength="10000" placeholder="Ex. : regarder deux voitures avec de la place pour les bagages…">${esc(state.notes)}</textarea></label></section></div><aside class="plan-aside"><div class="map-panel"><h3>Notre boucle</h3>${mapControls('notebook',true,'notebook')}${mapSvg(route.stops.map(s=>s.id),route.stops.map(s=>s.id),false,{key:'notebook',routeId:route.templateId,routes:[{...route,assessment:a}]})}<p>Liaisons schématiques · voir les trajets dans Google Maps.</p></div><section class="panel"><h3>Le voyage en chiffres</h3><div class="stack" style="gap:14px;margin-top:18px"><div><strong>${num(a.km)} km</strong><p class="hint">entre les étapes, par véhicule</p></div><div><strong>${E.formatTime(a.drive)}</strong><p class="hint">de conduite entre les étapes</p></div><div><strong>${E.formatTime(a.localDrive)}</strong><p class="hint">de conduite locale planifiée</p></div><div><strong>${E.formatTime(a.pauses)}</strong><p class="hint">de pauses prévues, en plus</p></div><div><strong>${a.transfers} journées de transfert</strong><p class="hint">sur ${a.expectedNights+1} jours sur place</p></div></div></section><section class="panel"><h3>Ça nous ressemble ?</h3><div class="small muted" style="font-size:11px;line-height:1.8;margin-top:13px">${routeExplanation(route,a)}</div></section></aside></div>`;
 }
 function openDialog(content,kind){if(ui.modal?.kind==='map'&&kind.kind!=='map')finishMap();ui.modal=kind;const dlg=$('#dialog');dlg.classList.toggle('map-dialog',kind.kind==='map');dlg.innerHTML=`<button class="dialog-close" data-action="close" aria-label="Fermer">${icon('close')}</button>${content}`;if(!dlg.open)dlg.showModal();}
 function destinationContent(id,inMap=false){
  const d=E.byId[id],p=PHOTOS[id],v=E.votesFor(state,id);
  const containing=DATA.templates.filter(t=>t.stops.some(s=>[s.id,...s.alternatives].includes(id)));
  const compatible=containing.some(t=>{const ids=t.stops.map(s=>[s.id,...s.alternatives].includes(id)?id:s.id);return E.evaluate(state,E.allocate(state,t,ids)).feasible;});
  const status=!containing.length?'À explorer dans un autre cadre':compatible?'Présent dans un circuit compatible':'À ajuster selon les réglages';
  return `${galleryMarkup(id)}<div class="dialog-body"><div class="row between wrap"><span class="eyebrow" style="color:var(--orange)">${esc(d.region)}</span><span class="badge ${compatible?'':'warm'}">${status}</span></div><h2 ${inMap?'':'id="dialog-title"'}>${esc(d.name)}</h2><p class="dialog-intro">${esc(d.intro)}</p><div class="detail-meta"><div class="meta-box">${d.days[0]===d.days[1]?d.days[0]:d.days.join(' à ')} jour${d.days[1]>1?'s':''}<span>Durée conseillée</span></div><div class="meta-box">${effort[d.effort]}<span>Effort des activités</span></div><div class="meta-box">${v.count?`${v.average.toFixed(1).replace('.',',')} / 5`:'Pas encore noté'}<span>${v.count} avis sur 9</span></div></div><div class="alert"><strong>En février</strong><br>${esc(d.feb)}${d.roadNote?`<br>${esc(d.roadNote)}`:''}${!containing.length&&!d.roadNote?'<br>Cette destination n’est pas incluse dans les circuits préparés au départ de Buenos Aires.':''}${containing.length&&!compatible?'<br>Le circuit associé dépasse actuellement une limite de conduite ou de durée. Voir les circuits pour le détail.':''}</div><h3 style="font-family:Georgia,serif;font-size:23px;font-weight:400;margin-top:26px">À ne pas manquer</h3>${d.activities.map((a,i)=>`<div class="activity"><span class="activity-n">0${i+1}</span><div><h3>${esc(a.name)} <span class="badge" style="font-size:9px;margin-left:6px">≈ ${E.formatTime(a.hours*60)}</span></h3><p>${esc(a.tip)}</p></div></div>`).join('')}${!d.hidden?`<div class="dialog-vote"><div class="row between"><div><strong style="font-size:12px">L’envie de ${esc(active().name)}</strong><p class="small muted" style="font-size:10px">1 = pas envie · 5 = coup de cœur</p></div>${stars(id,true)}</div></div>`:''}<div class="row between wrap" style="margin-top:20px"><a class="btn sm" href="https://www.google.com/maps/search/?api=1&query=${d.lat}%2C${d.lon}" target="_blank" rel="noopener noreferrer">${icon('pin')} Situer dans Google Maps</a>${p?.article?`<a href="${esc(p.article)}" target="_blank" rel="noopener noreferrer" class="small">En savoir plus ↗</a>`:''}</div></div>`;
 }
 function destinationDialog(id){if(!E.byId[id])return;if(ui.modal?.kind==='map'){showMapPlace(id);return;}ui.selectedPlace=id;openDialog(destinationContent(id),{kind:'destination',id});highlightPlaces();}
 function credit(p){return `<p class="photo-credit">Photo : ${esc(p.author)} · <a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)}</a> · ${p.licenseUrl?`<a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a>`:esc(p.license)}. Image redimensionnée et recadrée à l’affichage.</p>`;}
 function settingsDialog(){openDialog(`<div class="dialog-body"><div class="eyebrow" style="color:var(--orange)">LE CADRE DU VOYAGE</div><h2 id="dialog-title">Du temps pour en profiter.</h2><p class="dialog-intro">Voyage international du 3 au 17 février 2027. Les jours sur place sont distincts des jours de vol.</p><form id="settingsForm"><div class="settings-grid"><label>Arrivée en Argentine<input type="date" name="arrival" value="${state.settings.arrival}" min="2027-02-03" max="2027-02-16" required></label><label>Départ d’Argentine<input type="date" name="departure" value="${state.settings.departure}" min="2027-02-04" max="2027-02-17" required></label><label class="wide">Conduite maximum par jour<select name="maxDrive">${[1,2,3,4,4.5,5,5.5,6,6.5,7,8].map(h=>`<option value="${h}" ${state.settings.maxDrive===h?'selected':''}>${String(h).replace('.',',')} heures au volant · pauses en plus</option>`).join('')}</select></label><label class="checkbox wide"><input type="checkbox" name="confirmed" ${state.settings.confirmed?'checked':''}>Ces dates sur place correspondent à nos vols réservés.</label></div><div class="alert">Le retour en voiture à Buenos Aires est prévu au plus tard la veille du départ. Une journée avec plusieurs trajets cumule leur durée.</div><p id="settingsError" class="settings-form-error" role="alert"></p><div class="settings-actions"><button type="button" class="btn" data-action="close">Annuler</button><button type="submit" class="btn primary">Enregistrer les réglages</button></div></form></div>`,{kind:'settings'});}
 function sourcesDialog(){openDialog(`<div class="dialog-body"><div class="eyebrow" style="color:var(--orange)">EN TOUTE TRANSPARENCE</div><h2 id="dialog-title">Sources, photos & méthode.</h2><div class="stack"><section><h3>Un outil pour choisir ensemble</h3><p class="hint" style="margin-top:10px;font-size:12px">Ces douze circuits ont été composés pour les contraintes du groupe, en s’appuyant sur les sources touristiques ci-dessous et des trajets documentés. Ce ne sont pas douze itinéraires repris tels quels sur Internet. Les votes classent les variantes compatibles ; le moteur ne crée pas de nouveaux trajets. Pour chaque lieu, un vote explicite prime sur les thèmes. Sans avis pertinent, le score reste neutre. Les répondants ont tous le même poids ; les haltes de liaison n’augmentent pas l’affinité. Les douze familles sont affichées, compatibles en premier, avec un repère sur les trois meilleures. Le temps de conduite départage les égalités.</p></section><section><h3>Temps et distances</h3><p class="hint" style="font-size:12px;margin-top:10px">Trajets vérifiés en octobre 2026 avec OSRM et les données OpenStreetMap. Durées de base majorées de 15 % puis arrondies au quart d’heure supérieur, sans trafic en temps réel. Minimum de 3 h 30 pour la piste Mercedes–Iberá. Pauses de 20 minutes par tranche de 2 h de conduite. Les distances affichées couvrent les transferts ; les kilomètres des excursions locales ne sont pas additionnés. La durée des excursions en voiture planifiées compte dans la limite journalière. Les autres déplacements locaux restent à prévoir.</p><p class="small" style="margin-top:9px"><a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener noreferrer">OSRM / FOSSGIS</a> · © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">contributeurs OpenStreetMap, ODbL</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener noreferrer">Corriger la carte</a></p></section><section><h3>Pour préparer le séjour</h3><div class="source-list" style="margin-top:13px">${DATA.sources.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`).join('')}</div><p class="small muted" style="margin-top:15px">Descriptions de préparation, pas de réservation ni de tarifs en temps réel. Horaires, état des routes et accès aux sites à confirmer avant le départ. Les cartes dessinées dans l’outil sont schématiques.</p></section><section><h3>Un fichier, vos données</h3><p class="small muted" style="margin-top:10px">${BOOT?'Les réponses sont enregistrées sur Neon et partagées entre les neuf voyageurs. Chaque vote est sauvegardé séparément. La synthèse se met à jour toutes les dix secondes. Toute personne qui possède ce lien peut modifier les profils et le carnet : partagez-le uniquement avec le groupe. L’export JSON reste une copie de secours ; une restauration remplace la préparation commune après confirmation.':'Tout fonctionne dans ce navigateur, sans compte ni serveur. Les liens externes nécessitent Internet. Exportez une sauvegarde JSON avant de changer d’appareil ou de déplacer le HTML. Un import remplace les choix actuels après confirmation.'}</p></section><section><p class="small muted">Photographies redimensionnées et compressées en WebP pour un chargement plus léger ; sources et licences indiquées ci-dessous.</p><h3 style="margin-bottom:17px">Les ${Object.values(PHOTOS).reduce((n,p)=>n+p.images.length,0)} photographies</h3><div class="credits-list">${Object.values(PHOTOS).map(p=>`<div class="credit-item"><strong>${esc(E.byId[p.id]?.name||p.title)}</strong>${p.images.map(credit).join('')}</div>`).join('')}</div></section></div></div>`,{kind:'sources'});}
 function resetDialog(){openDialog(`<div class="dialog-body"><h2 id="dialog-title">Repartir d’une page blanche ?</h2><p class="dialog-intro">${BOOT?'Les neuf profils, les votes et le carnet de tout le groupe seront réinitialisés.':'Les neuf profils, les votes et le carnet de ce navigateur seront réinitialisés.'} Tu peux d’abord sauvegarder la préparation actuelle.</p><div class="settings-actions wrap"><button class="btn" data-action="export">${icon('download')} Sauvegarder</button><button class="btn" data-action="close">Annuler</button><button class="btn primary" data-action="confirm-reset">Recommencer</button></div></div>`,{kind:'reset'});}
 function finishMap(){if(ui.largeContext){const c=ui.largeContext;const v=ui.mapViews[c.key]||ui.mapBases[c.key];if(v)ui.mapViews[c.source]=[...v];}applyMapViews();}
 function closeDialog(){if(ui.modal?.kind==='map')finishMap();$('#dialog').close();ui.modal=null;ui.hoverPlace=null;ui.hoverRoute=null;highlightPlaces();highlightRoutes();}
 function exportBackup(){const blob=new Blob([JSON.stringify(pack(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='argentine-a9-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sauvegarde exportée. Garde-la avec ton fichier HTML.');}
 function preparePrint(){
  if(!state.selected){toast('Choisis un circuit pour créer le carnet imprimable.');return false;}
  const t=DATA.templates.find(t=>t.id===state.selected.templateId),a=E.evaluate(state,state.selected);
  $('#printArea').innerHTML=`<header class="print-header"><div class="eyebrow">ARGENTINE À 9 · NOTRE CARNET</div><h1>${esc(t.title)}</h1><p class="print-meta">Voyage international : 3 — 17 février 2027<br>Sur place : ${dateFmt(state.settings.arrival)} — ${dateFmt(state.settings.departure)} · ${a.totalNights} nuits<br>${state.profiles.map(p=>esc(p.name)).join(' · ')}<br>${num(a.km)} km entre étapes · ${E.formatTime(a.drive)} de conduite inter-étapes + ${E.formatTime(a.localDrive)} de conduite locale · ${E.formatTime(a.pauses)} de pauses<br>Maximum ${state.settings.maxDrive} h de conduite par jour · ${state.settings.confirmed?'dates confirmées':'dates provisoires'}</p></header>${assessmentAlerts(a)}<div class="map-panel"><h3>La boucle · liaisons schématiques</h3>${mapSvg(state.selected.stops.map(s=>s.id),state.selected.stops.map(s=>s.id),false,{key:'print',routeId:state.selected.templateId,routes:[{...state.selected,assessment:a}]})}</div><h2>Notre itinéraire</h2>${itineraryMarkup(a)}${state.notes?`<h2>Nos notes</h2><p class="print-notes">${esc(state.notes)}</p>`:''}<h2>À vérifier avant de partir</h2><p>Vols et heures d’aéroport, location des véhicules, conditions de route, réservations pour neuf, horaires et accès aux activités. Les photos, tarifs et disponibilités ne constituent pas une réservation.</p><p class="photo-credit">Données routières : OSRM / © contributeurs OpenStreetMap, ODbL · vérifications d’octobre 2026. Conduite estimée avec marge de 15 %. Sources touristiques : Visit Argentina et La Ruta Natural. Les liens Maps permettent de vérifier chaque trajet.</p>`;return true;
 }
 function updateAfterVote(){const focus=document.activeElement?.dataset.focus;const modal=ui.modal,scroll=$('#dialog').scrollTop;save();render();if(modal?.kind==='destination'){destinationDialog(modal.id);$('#dialog').scrollTop=scroll;}else if(modal?.kind==='map'){const panel=$('.large-map-aside'),top=panel?.scrollTop||0;renderMapPanel();if(panel)panel.scrollTop=top;}if(focus){[...$('#dialog').querySelectorAll('[data-focus]')].find(el=>el.dataset.focus===focus)?.focus({preventScroll:true});}}
 const M=TripMap;
 const routeColors=['#be5d37','#347d69','#8c7b25','#9e526f','#457799','#6e5fa6','#c08b24','#557d38','#a04b43','#16818c','#8d5b32','#4958b7'];
 const routeColor=id=>routeColors[Math.max(0,DATA.templates.findIndex(t=>t.id===id))%routeColors.length];
 const routeResults=()=>ui.routeResult||E.suggestions(state);
 const findRoute=id=>routeResults().catalog.find(r=>r.templateId===id);
 const galleryImages=id=>PHOTOS[id]?.images||(PHOTOS[id]?[PHOTOS[id]]:[]);
 const fullExplorer=()=>ui.region==='all'&&!ui.query&&ui.theme==='all'&&ui.scope==='all';
 const photoIndex=id=>Math.min(ui.gallery[id]||0,Math.max(0,galleryImages(id).length-1));
 const selectedPhoto=id=>galleryImages(id)[photoIndex(id)];
 function galleryMarkup(id){const images=galleryImages(id);if(!images.length)return '';const index=photoIndex(id),p=images[index];return `<section class="gallery" data-gallery="${id}" aria-label="Photos de ${esc(E.byId[id].name)}"><div class="gallery-stage"><button class="gallery-open" data-action="photo-open" data-id="${id}" aria-label="Agrandir la photo de ${esc(E.byId[id].name)}"><img src="${p.data}" alt="${esc(p.title)}" decoding="async"></button><button class="gallery-arrow prev" data-action="photo-step" data-id="${id}" data-step="-1" aria-label="Photo précédente">‹</button><button class="gallery-arrow next" data-action="photo-step" data-id="${id}" data-step="1" aria-label="Photo suivante">›</button><span class="gallery-counter" aria-live="polite">${index+1} / ${images.length} photos</span></div><div class="gallery-thumbs">${images.map((im,i)=>`<button data-action="photo-index" data-id="${id}" data-index="${i}" aria-label="Voir la photo ${i+1} de ${esc(E.byId[id].name)}" aria-pressed="${index===i}" class="${index===i?'active':''}"><img src="${im.data}" alt="" loading="lazy"></button>`).join('')}</div><div class="gallery-credit">${credit(p)}</div></section>`;}
 function updateGallery(id,index){const focus=document.activeElement?.dataset,focusAction=focus?.action,focusIndex=focus?.index,focusStep=focus?.step;const n=galleryImages(id).length;if(!n)return;ui.gallery[id]=(index+n)%n;document.querySelectorAll(`[data-gallery="${id}"]`).forEach(el=>{el.outerHTML=galleryMarkup(id);});if($('#photoDialog').open)renderPhotoDialog(id);if(['photo-step','photo-index'].includes(focusAction)){const scope=$('#photoDialog').open?$('#photoDialog'):$('#dialog');scope.querySelector(`[data-action="${focusAction}"][${focusAction==='photo-step'?'data-step':'data-index'}="${focusAction==='photo-step'?focusStep:focusIndex}"]`)?.focus({preventScroll:true});}}
 function renderPhotoDialog(id){const p=selectedPhoto(id),n=galleryImages(id).length;$('#photoDialog').innerHTML=`<button class="dialog-close" data-action="close-photo" aria-label="Fermer la photo">${icon('close')}</button><div class="lightbox-head">${esc(E.byId[id].name)} <span>${photoIndex(id)+1} / ${n}</span></div><div class="lightbox-stage"><button class="gallery-arrow prev" data-action="photo-step" data-id="${id}" data-step="-1" aria-label="Photo précédente">‹</button><img src="${p.data}" alt="${esc(p.title)}"><button class="gallery-arrow next" data-action="photo-step" data-id="${id}" data-step="1" aria-label="Photo suivante">›</button></div><div class="lightbox-credit">${credit(p)}</div>`;}
 function openPhoto(id){ui.lightbox=id;renderPhotoDialog(id);$('#photoDialog').showModal();}
 function mapControls(key,expand=true,context='explore',routeId=''){return `<div class="map-controls" aria-label="Commandes de la carte"><button class="btn sm" data-action="map-zoom" data-map-key="${key}" data-factor="0.65" aria-label="Zoomer sur la carte">+</button><button class="btn sm" data-action="map-zoom" data-map-key="${key}" data-factor="1.54" aria-label="Dézoomer la carte">−</button><button class="btn sm" data-action="map-reset" data-map-key="${key}">Recentrer</button>${expand?`<button class="btn sm expand-map" data-action="map-expand" data-context="${context}" data-route-id="${routeId}">${icon('map')} Agrandir la carte</button>`:''}</div>`;}
 function mapSvg(ids,route=null,full=false,options={}){
  const key=options.key||'static-'+(route?route.join('-'):ids.join('-')),routes=options.routes|| (route?[{templateId:options.routeId||'cote',stops:route.map(id=>({id})),assessment:{feasible:true}}]:[]);
  const unique=[...new Set([...ids,...routes.flatMap(r=>r.stops.map(s=>s.id))])],places=unique.map(id=>E.byId[id]).filter(Boolean);
  const coords=places.map(d=>[d.lon,d.lat]),base=M.fit(coords,full);ui.mapBases[key]=base;ui.mapIds[key]=unique;
  const view=ui.mapViews[key]||base;
  const polygon=coords=>coords.map(M.project).map(p=>p.join(',')).join(' ');
  return `<svg class="map-svg interactive-map ${options.comparison?'comparison-map':''}" data-map-key="${key}" data-comparison="${!!options.comparison}" viewBox="${view.join(' ')}" role="group" aria-label="Carte schématique des destinations" tabindex="0"><rect x="-2000" y="-2000" width="5000" height="5000" fill="#e8f0ec"/><polygon class="map-country" points="${polygon(M.country)}"/><polygon class="map-country" points="${polygon([[-68.6,-52.6],[-68.6,-54.9],[-66,-55.1],[-65,-54.6]])}"/><g class="map-geography"><text x="175" y="400" transform="rotate(-78 175 400)">ARGENTINE</text><text x="460" y="660" transform="rotate(-78 460 660)">OCÉAN ATLANTIQUE</text></g>${routes.map(r=>{const t=DATA.templates.find(t=>t.id===r.templateId);return `<g class="route-layer ${r.assessment.feasible?'':'incompatible'}" data-route-layer="${r.templateId}" ${options.comparison&&!ui.visibleRoutes.has(r.templateId)?'hidden':''}><polyline class="route-hit" data-action="map-route" data-route-id="${r.templateId}" role="button" tabindex="0" aria-label="Voir le circuit ${esc(t?.title||'sélectionné')}" points="${polygon(r.stops.map(s=>[E.byId[s.id].lon,E.byId[s.id].lat]))}"/><polyline class="route-line" style="stroke:${routeColor(r.templateId)}" points="${polygon(r.stops.map(s=>[E.byId[s.id].lon,E.byId[s.id].lat]))}"/></g>`;}).join('')}${places.map(d=>{const [x,y]=M.project([d.lon,d.lat]);return `<g class="place ${ui.selectedPlace===d.id?'is-highlight':''}" role="button" tabindex="0" data-action="detail" data-id="${d.id}" data-place-id="${d.id}" aria-label="Découvrir ${esc(d.name)}" transform="translate(${x} ${y})"><title>${esc(d.name)}</title><g class="pin-symbol"><circle class="pin-hit" r="13"/><circle class="pin-halo" r="14"/><circle class="map-pin" r="5.5"/><text class="pin-label ${unique.length<9||d.id==='ba'?'label-visible':''}" x="12" y="4">${esc(d.name)}</text></g></g>`;}).join('')}</svg>`;
 }
 function applyMapViews(){document.querySelectorAll('.interactive-map').forEach(svg=>{const key=svg.dataset.mapKey,v=ui.mapViews[key]||ui.mapBases[key];if(!v)return;svg.setAttribute('viewBox',v.join(' '));const scale=Math.max(v[2]/Math.max(1,svg.clientWidth||480),v[3]/Math.max(1,svg.clientHeight||500));svg.querySelectorAll('.pin-symbol').forEach(g=>g.setAttribute('transform',`scale(${scale})`));});highlightPlaces();highlightRoutes();}
 function highlightPlaces(id=ui.hoverPlace||ui.selectedPlace){document.querySelectorAll('.place').forEach(g=>g.classList.toggle('is-highlight',g.dataset.id===id));document.querySelectorAll('[data-hover-place]').forEach(el=>el.classList.toggle('place-focused',el.dataset.hoverPlace===id));}
 function highlightRoutes(id=ui.hoverRoute||ui.selectedRoute){document.querySelectorAll('.interactive-map').forEach(svg=>{svg.classList.toggle('has-route-focus',!!id&&!!svg.querySelector(`[data-route-layer="${id}"]:not([hidden])`));svg.querySelectorAll('.route-layer').forEach(g=>g.classList.toggle('route-focused',g.dataset.routeLayer===id));});document.querySelectorAll('[data-hover-route]').forEach(el=>el.classList.toggle('route-focused-card',el.dataset.hoverRoute===id));}
 function routeLegend(){return `<div class="route-legend"><div class="legend-actions"><button class="text-link" data-action="routes-visibility" data-mode="all">Tout afficher</button><button class="text-link" data-action="routes-visibility" data-mode="none">Tout masquer</button><button class="text-link" data-action="routes-visibility" data-mode="compatible">Circuits compatibles</button></div><p class="map-note">Trait continu : compatible · pointillés : à ajuster.</p><div class="legend-items">${routeResults().catalog.map(r=>{const t=DATA.templates.find(t=>t.id===r.templateId);return `<div class="legend-row" data-hover-route="${t.id}"><label><input type="checkbox" data-route-toggle="${t.id}" ${ui.visibleRoutes.has(t.id)?'checked':''} aria-label="Afficher ${esc(t.title)}"><span class="route-swatch ${r.assessment.feasible?'':'dashed'}" style="--route-color:${routeColor(t.id)}"></span></label><button data-action="map-route" data-route-id="${t.id}">${esc(t.family)}<small>${r.assessment.feasible?'Compatible':'À ajuster'}</small></button></div>`;}).join('')}</div></div>`;}
 function syncVisibility(){document.querySelectorAll('[data-comparison="true"] .route-layer').forEach(g=>g.toggleAttribute('hidden',!ui.visibleRoutes.has(g.dataset.routeLayer)));document.querySelectorAll('[data-route-toggle]').forEach(el=>el.checked=ui.visibleRoutes.has(el.dataset.routeToggle));document.querySelectorAll('[data-map-count]').forEach(el=>el.textContent=ui.visibleRoutes.size+' circuits affichés');highlightRoutes();}
 function comparisonMap(){const routes=routeResults().catalog;return `<aside class="comparison-aside"><div class="map-panel"><div class="row between"><h3>Vos voyages sur la carte</h3><span class="badge" data-map-count>${ui.visibleRoutes.size} circuits affichés</span></div><p class="map-note">Survolez un circuit pour le repérer.</p>${mapControls('compare',true,'compare')}${mapSvg([],null,false,{key:'compare',routes,comparison:true})}<p class="map-note">Liaisons schématiques · sans connexion</p>${routeLegend()}</div></aside>`;}
 function largeMapContext(context,id){
  if(context==='compare')return {ids:[],routes:routeResults().catalog,key:'compare',comparison:true,title:'Tous les itinéraires'};
  if(context==='notebook'&&state.selected){const r={...state.selected,assessment:E.evaluate(state,state.selected)};return {ids:[],routes:[r],key:'notebook',title:'Notre itinéraire'};}
  if(context==='route'){const r=findRoute(id);if(r)return {ids:[],routes:[r],key:'route-'+id,title:DATA.templates.find(t=>t.id===id).title};}
  return {ids:filteredPlaces().map(d=>d.id),routes:[],key:'explore',title:'L’Argentine, en grand'};
 }
 function openLargeMap(context='explore',id=''){
  const c=largeMapContext(context,id),key=c.key+'-large';
  if(ui.mapViews[c.key]||ui.mapBases[c.key])ui.mapViews[key]=[...(ui.mapViews[c.key]||ui.mapBases[c.key])];
  ui.largeContext={context,id,source:c.key,key};
  openDialog(`<div class="large-map-header"><div><div class="eyebrow">PRENDRE LE TEMPS DE SE REPÉRER</div><h2 id="dialog-title">${esc(c.title)}</h2></div>${mapControls(key,false)}</div><div class="large-map-layout"><div class="large-map-canvas">${mapSvg(c.ids,null,context==='explore'&&fullExplorer(),{key,routes:c.routes,comparison:c.comparison})}<p class="map-help">Glisser pour déplacer · + / − pour zoomer · flèches du clavier pour déplacer<br>Liaisons schématiques, pas un tracé routier.</p></div><aside class="large-map-aside"><div id="mapDetail"></div>${c.comparison?routeLegend():`<div class="map-place-list"><h3>Les lieux de la carte</h3>${[...new Set([...c.ids,...c.routes.flatMap(r=>r.stops.map(s=>s.id))])].map(id=>`<button data-action="map-place" data-id="${id}" data-hover-place="${id}">${icon('pin')}${esc(E.byId[id].name)}</button>`).join('')}</div>`}</aside></div>`,{kind:'map'});
  $('#dialog').classList.add('map-dialog');renderMapPanel();applyMapViews();
 }
 function renderMapPanel(){const el=$('#mapDetail');if(!el)return;if(ui.mapPanel?.type==='place'){el.innerHTML=`<div class="map-detail-head"><button class="text-link" data-action="clear-map-panel">← Retour à la liste</button><button class="btn sm" data-action="map-locate" data-id="${ui.mapPanel.id}">Centrer ici</button></div>${destinationContent(ui.mapPanel.id,true)}`;}
  else if(ui.mapPanel?.type==='route'){const r=ui.largeContext?.context==='notebook'&&state.selected?{...state.selected,assessment:E.evaluate(state,state.selected)}:findRoute(ui.mapPanel.id);el.innerHTML=r?`<div class="map-detail-head"><button class="text-link" data-action="clear-map-panel">← Tous les circuits</button></div>${routePanel(r)}`:'';}
  else el.innerHTML='<div class="map-empty"><h3>Un pays à explorer ensemble.</h3><p>Cliquez sur un point pour voir ses photos et incontournables, ou sur un circuit pour comparer ses étapes.</p></div>';
 }
 function routePanel(r){const t=DATA.templates.find(t=>t.id===r.templateId),a=r.assessment;return `<div class="route-panel"><span class="badge ${a.feasible?'':'warm'}">${a.feasible?'Compatible avec vos réglages':'Hors de vos réglages actuels'}</span><h3>${esc(t.title)}</h3><p>${esc(t.subtitle)}</p><p><strong>${a.totalNights} nuits · ${num(a.km)} km · ${E.formatTime(a.drive)} au volant</strong></p>${!a.feasible?`<div class="alert error"><ul>${a.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<ol class="route-stop-list">${r.stops.map((s,i)=>{const leg=i?E.leg(r.stops[i-1].id,s.id):null;return `<li data-hover-place="${s.id}"><button data-action="map-place" data-id="${s.id}">${esc(E.byId[s.id].name)}</button><span>${s.nights} nuit${s.nights>1?'s':''}</span>${i?`<small>${leg?`${num(leg.km)} km · ${E.formatTime(leg.minutes)} + ${E.formatTime(E.breaks(leg.minutes))} de pauses`:'Trajet non documenté'}</small>`:''}</li>`;}).join('')}</ol>${ui.largeContext?.context==='notebook'?'<button class="btn primary" data-action="close">Retour au carnet</button>':`<button class="btn primary" data-action="choose-route" data-route-id="${t.id}" ${a.feasible?'':'disabled'}>${a.feasible?'Choisir & ajuster':'À ajuster avant de choisir'}</button>`}<p class="map-note">Les distances excluent les excursions locales.</p></div>`;}
 function showMapRoute(id){ui.selectedRoute=id;ui.hoverRoute=null;ui.selectedPlace=null;ui.mapPanel={type:'route',id};if(ui.modal?.kind!=='map')openLargeMap(ui.tab==='notebook'?'notebook':'compare');else renderMapPanel();highlightRoutes();highlightPlaces();}
 function showMapPlace(id,center=false){ui.selectedRoute=null;ui.hoverRoute=null;ui.selectedPlace=id;ui.hoverPlace=null;ui.mapPanel={type:'place',id};renderMapPanel();highlightPlaces();highlightRoutes();if(center)locatePlace(id);}
 function locatePlace(id){const c=ui.largeContext;if(!c)return;const d=E.byId[id],[x,y]=M.project([d.lon,d.lat]),v=ui.mapViews[c.key]||ui.mapBases[c.key];ui.mapViews[c.key]=[x-v[2]/2,y-v[3]/2,v[2],v[3]];applyMapViews();}
 function mapCommand(b){const key=b.dataset.mapKey;if(!key)return;const v=ui.mapViews[key]||ui.mapBases[key];if(b.dataset.action==='map-reset'){
   const svg=document.querySelector(`svg[data-map-key="${key}"]`);const ids=svg?.dataset.comparison==='true'?routeResults().catalog.filter(r=>ui.visibleRoutes.has(r.templateId)).flatMap(r=>r.stops.map(s=>s.id)):ui.mapIds[key]||[];
   ui.mapViews[key]=M.fit(ids.map(id=>[E.byId[id].lon,E.byId[id].lat]),false);
  }else ui.mapViews[key]=M.zoom(v,Number(b.dataset.factor));applyMapViews();}
 let mapDrag=null,ignoreMapClickUntil=0;
 document.addEventListener('pointerdown',event=>{const svg=event.target.closest('.interactive-map');if(!svg||event.button!==0)return;const v=ui.mapViews[svg.dataset.mapKey]||ui.mapBases[svg.dataset.mapKey];mapDrag={svg,key:svg.dataset.mapKey,x:event.clientX,y:event.clientY,start:[...v],moved:false};});
 document.addEventListener('pointermove',event=>{if(!mapDrag)return;const d=mapDrag,dx=event.clientX-d.x,dy=event.clientY-d.y;if(Math.abs(dx)+Math.abs(dy)>5)d.moved=true;if(!d.moved)return;const rect=d.svg.getBoundingClientRect(),scale=Math.max(d.start[2]/rect.width,d.start[3]/rect.height);ui.mapViews[d.key]=M.pan(d.start,-dx*scale,-dy*scale);applyMapViews();});
 document.addEventListener('pointerup',()=>{if(mapDrag?.moved)ignoreMapClickUntil=Date.now()+300;mapDrag=null;});
 document.addEventListener('pointercancel',()=>{mapDrag=null;});
 document.addEventListener('click',event=>{if(Date.now()<ignoreMapClickUntil&&event.target.closest('.interactive-map')){event.stopImmediatePropagation();event.preventDefault();}},true);
 function hoverTarget(event,enter){const place=event.target.closest('[data-hover-place],.place');const route=event.target.closest('[data-hover-route],[data-route-layer]');if(place){if(event.relatedTarget&&place.contains(event.relatedTarget))return;ui.hoverPlace=enter?(place.dataset.hoverPlace||place.dataset.id):null;highlightPlaces();}if(route){if(event.relatedTarget&&route.contains(event.relatedTarget))return;ui.hoverRoute=enter?(route.dataset.hoverRoute||route.dataset.routeLayer):null;highlightRoutes();}}
 document.addEventListener('pointerover',e=>hoverTarget(e,true));document.addEventListener('pointerout',e=>hoverTarget(e,false));document.addEventListener('focusin',e=>hoverTarget(e,true));document.addEventListener('focusout',e=>hoverTarget(e,false));
 document.addEventListener('keydown',event=>{
  if($('#photoDialog').open){if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();updateGallery(ui.lightbox,photoIndex(ui.lightbox)+(event.key==='ArrowRight'?1:-1));}return;}
  const svg=event.target.closest('.interactive-map');if(!svg||event.target!==svg)return;const key=svg.dataset.mapKey,v=ui.mapViews[key]||ui.mapBases[key];const directions={ArrowLeft:[-.15,0],ArrowRight:[.15,0],ArrowUp:[0,-.15],ArrowDown:[0,.15]};
  if(directions[event.key]){event.preventDefault();const [x,y]=directions[event.key];ui.mapViews[key]=M.pan(v,v[2]*x,v[3]*y);applyMapViews();}else if(['+','=','-','Home'].includes(event.key)){event.preventDefault();ui.mapViews[key]=event.key==='Home'?[...ui.mapBases[key]]:M.zoom(v,event.key==='-'?1.54:.65);applyMapViews();}
 });
 window.addEventListener('resize',applyMapViews);

 document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action]');if(!b||b.disabled)return;
  const a=b.dataset.action;
  if(a==='sync-retry')cloud.refresh();
  else if(a==='sync-conflict')syncConflictDialog();
  else if(a==='sync-use-online'||a==='sync-use-mine'){cloud.resolve(a==='sync-use-mine');closeDialog();}
  else if(a==='photo-step')updateGallery(b.dataset.id,photoIndex(b.dataset.id)+Number(b.dataset.step));
  else if(a==='photo-index')updateGallery(b.dataset.id,Number(b.dataset.index));
  else if(a==='photo-open')openPhoto(b.dataset.id);
  else if(a==='close-photo')$('#photoDialog').close();
  else if(a==='map-expand'){ui.mapPanel=null;openLargeMap(b.dataset.context,b.dataset.routeId);}
  else if(a==='map-zoom'||a==='map-reset')mapCommand(b);
  else if(a==='map-route')showMapRoute(b.dataset.routeId);
  else if(a==='map-place')showMapPlace(b.dataset.id);
  else if(a==='map-locate')locatePlace(b.dataset.id);
  else if(a==='clear-map-panel'){ui.mapPanel=null;ui.selectedPlace=null;ui.selectedRoute=null;renderMapPanel();highlightPlaces();highlightRoutes();}
  else if(a==='routes-visibility'){ui.visibleRoutes=new Set(b.dataset.mode==='none'?[]:routeResults().catalog.filter(r=>b.dataset.mode!=='compatible'||r.assessment.feasible).map(r=>r.templateId));syncVisibility();}
  else if(a==='edit-route')routeEditor(b.dataset.routeId);
  else if(a==='draft-rebalance'){const t=DATA.templates.find(t=>t.id===ui.routeDraft.templateId);ui.routeDraft=E.allocate(state,t,ui.routeDraft.stops.map(s=>s.id));routeEditor(t.id,true);}
  else if(a==='nav')navigate(b.dataset.tab);
  else if(a==='routes')navigate('routes');
  else if(a==='person'){state.active=b.dataset.id;save();render();if(ui.modal?.kind==='destination')destinationDialog(ui.modal.id);}
  else if(a==='next-person'){state.active=state.profiles[(state.profiles.findIndex(p=>p.id===state.active)+1)%9].id;save();render();}
  else if(a==='vote'){active().votes[b.dataset.id]=Number(b.dataset.score);updateAfterVote();}
  else if(a==='clear-vote'){delete active().votes[b.dataset.id];updateAfterVote();}
  else if(a==='theme'){active().themes[b.dataset.theme]=Number(b.dataset.value);save();render();}
  else if(a==='clear-theme'){delete active().themes[b.dataset.theme];save();render();}
  else if(a==='filter-theme'){ui.theme=b.dataset.theme;render();}
  else if(a==='view'){ui.map=b.dataset.map==='true';render();}
  else if(a==='clear-filters'){Object.assign(ui,{query:'',region:'all',theme:'all',scope:'all'});render();}
  else if(a==='detail')destinationDialog(b.dataset.id);
  else if(a==='close')closeDialog();
  else if(a==='settings')settingsDialog();
  else if(a==='sources')sourcesDialog();
  else if(a==='export')exportBackup();
  else if(a==='import')$('#importFile').click();
  else if(a==='confirm-import'){if(cloud){restoreCloud(ui.pendingImport,ui.pendingImportRevision);return;}state=ui.pendingImport;delete ui.pendingImport;closeDialog();save();render();toast('Les neuf profils et le carnet ont été restaurés.');}
  else if(a==='reset'){ui.resetRevision=cloud?.revision();resetDialog();}
  else if(a==='confirm-reset'){if(cloud){restoreCloud(E.defaultState(),ui.resetRevision);return;}state=E.defaultState();closeDialog();save();navigate('explore');toast('Le carnet a été réinitialisé.');}
  else if(a==='choose-route'){
   const candidate=b.dataset.draft?ui.routeDraft:findRoute(b.dataset.routeId);if(!candidate||!E.evaluate(state,candidate).feasible)return;closeDialog();
   const selected={templateId:candidate.templateId,stops:E.clone(candidate.stops)};
   if(state.selected){ui.pendingRoute=selected;openDialog(`<div class="dialog-body"><h2 id="dialog-title">Choisir ce nouveau circuit ?</h2><p class="dialog-intro">Les étapes et les nuits personnalisées du carnet actuel seront remplacées. Vos votes, profils et notes seront conservés.</p><div class="settings-actions"><button class="btn" data-action="close">Annuler</button><button class="btn primary" data-action="confirm-route">Choisir ce circuit</button></div></div>`,{kind:'replace-route'});}
   else{state.selected=selected;save();navigate('notebook');toast('Circuit ajouté au carnet. Vous pouvez ajuster les étapes.');}
  }
  else if(a==='confirm-route'){state.selected=ui.pendingRoute;delete ui.pendingRoute;closeDialog();save();navigate('notebook');}
  else if(a==='nights'){const s=state.selected?.stops[Number(b.dataset.index)];if(s){s.nights=Math.max(1,Math.min(14,s.nights+Number(b.dataset.delta)));save();render();}}
  else if(a==='rebalance'){const t=DATA.templates.find(t=>t.id===state.selected?.templateId);if(t){state.selected=E.allocate(state,t,state.selected.stops.map(s=>s.id));save();render();toast('Nuits réparties selon vos dates et vos envies.');}}
  else if(a==='print'){if(preparePrint())window.print();}
 });
 document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('g[data-action],polyline[data-action]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 document.addEventListener('input',event=>{
  if(event.target.dataset.draftNights!==undefined){ui.routeDraft.stops[Number(event.target.dataset.draftNights)].nights=Number(event.target.value);ui.routeDraft.assessment=E.evaluate(state,ui.routeDraft);$('[data-draft-alerts]').innerHTML=assessmentAlerts(ui.routeDraft.assessment);$('#dialog [data-draft="true"]').disabled=!ui.routeDraft.assessment.feasible;}
  if(event.target.id==='search'){ui.query=event.target.value;render();}
  if(event.target.id==='tripNotes'){state.notes=event.target.value;save();}
  if(event.target.id==='profileName'){active().name=event.target.value.trim().slice(0,40)||'Voyageur '+state.active.slice(1);save();renderSidebar();renderTop();const link=$('#main [data-action="nav"][data-tab="explore"]');if(link)link.textContent='Explorer les lieux pour '+active().name+' →';}
 });
 document.addEventListener('change',event=>{
  const el=event.target;
  if(el.dataset.routeToggle){el.checked?ui.visibleRoutes.add(el.dataset.routeToggle):ui.visibleRoutes.delete(el.dataset.routeToggle);syncVisibility();}
  if(el.dataset.draftStop!==undefined){ui.routeDraft.stops[Number(el.dataset.draftStop)].id=el.value;routeEditor(ui.routeDraft.templateId,true);}
  if(el.id==='regionFilter'){ui.region=el.value;render();}
  if(el.id==='scopeFilter'){ui.scope=el.value;render();}
  if(el.id==='profileName'){active().name=el.value.trim().slice(0,40)||'Voyageur '+state.active.slice(1);el.value=active().name;save();renderSidebar();renderTop();}
  if(el.dataset.stopIndex!==undefined&&state.selected){state.selected.stops[Number(el.dataset.stopIndex)].id=el.value;save();render();}
 });
 document.addEventListener('submit',event=>{
  if(event.target.id!=='settingsForm')return;event.preventDefault();
  const form=new FormData(event.target),settings={arrival:form.get('arrival'),departure:form.get('departure'),maxDrive:Number(form.get('maxDrive')),confirmed:form.get('confirmed')==='on'},errors=E.settingsErrors(settings);
  if(errors.length){$('#settingsError').textContent=errors.join(' ');return;}
  state.settings=settings;closeDialog();save();render();toast(state.selected?'Réglages enregistrés. Vérifiez les nuits du carnet.':'Réglages enregistrés. Les circuits ont été recalculés.');
 });
 $('#importFile').addEventListener('change',async event=>{
  const file=event.target.files[0];if(!file)return;
  try{
   if(file.size>2*1024*1024)throw new Error('Ce fichier est trop volumineux pour une sauvegarde de choix.');
   ui.pendingImport=E.parseBackup(JSON.parse(await file.text()));ui.pendingImportRevision=cloud?.revision();
   openDialog(`<div class="dialog-body"><h2 id="dialog-title">Restaurer cette préparation ?</h2><p class="dialog-intro">La sauvegarde contient neuf profils${ui.pendingImport.selected?' et un carnet de voyage':''}. ${BOOT?'Elle remplacera les réponses du groupe en ligne.':'Elle remplacera les choix présents dans ce navigateur.'}</p><p>${ui.pendingImport.profiles.map(p=>esc(p.name)+' : '+Object.keys(p.votes).length+' votes').join(' · ')}</p><div class="settings-actions wrap"><button class="btn" data-action="export">Sauvegarder les choix actuels</button><button class="btn" data-action="close">Annuler</button><button class="btn primary" data-action="confirm-import">Restaurer la sauvegarde</button></div></div>`,{kind:'import'});
  }catch(error){toast('Import impossible : '+(error instanceof SyntaxError?'le fichier JSON est illisible.':error.message));}
  event.target.value='';
 });
 $('#dialog').addEventListener('cancel',()=>{if(ui.modal?.kind==='map')finishMap();});
 $('#dialog').addEventListener('close',()=>{if($('#dialog').open)return;ui.modal=null;ui.hoverPlace=null;ui.hoverRoute=null;highlightPlaces();highlightRoutes();});
 $('#photoDialog').addEventListener('close',()=>{ui.lightbox=null;});
 $('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const rect=event.target.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog();}});
 window.addEventListener('beforeprint',()=>{if(state.selected)preparePrint();});
 if(BOOT){state=E.clone(BOOT.snapshot.state);try{const local=JSON.parse(localStorage.getItem(KEY)||'null');if(/^p[1-9]$/.test(local?.active))state.active=local.active;}catch{}cloud=A9Cloud.create({snapshot:BOOT.snapshot,url:BOOT.url,key:KEY+':pending',storage:localStorage,onChange:receiveCloud,onStatus:s=>{cloudStatus=s;renderSaveStatus();},onError:toast});render();cloud.start();setInterval(()=>{if(!document.hidden)cloud.refresh();},10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)cloud.refresh();});window.addEventListener('online',()=>cloud.refresh());window.addEventListener('beforeunload',e=>{if(cloud.status().count){e.preventDefault();e.returnValue='';}});}else render();if(initialError)toast(initialError);
})();
